// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL, LogFile} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;

    function setUp() public { c = new PRIVATE_ETH_CELL(); }

    function testFuzz_property(address actor, uint256 amount, uint256 minSum, uint256 preBalance) public {
        // Wide admissible domain: actor must be a plausible EOA (not this test / c) so we can prank it.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // Deploy a real LogFile so Deposits/Collects can log without reverting.
        LogFile logFile = new LogFile();

        // Initialize MinSum and Log FIRST (Initialized not yet set, SetLogFile/SetMinSum are open).
        c.SetLogFile(address(logFile));
        c.SetMinSum(minSum);
        c.Initialized();

        // Keep preBalance below MinSum so the reference refuses to change it in Collect.
        // Allow preBalance == 0 too; bound MinSum to at least 1 so minSum > preBalance is achievable.
        minSum = bound(minSum, 1, type(uint128).max);
        preBalance = bound(preBalance, 0, minSum - 1);

        // Fund the actor and deposit to reach exactly preBalance.
        vm.deal(actor, preBalance);
        vm.prank(actor);
        c.Deposit{value: preBalance}();

        // __am must satisfy the weakened mutant's only guard: balances[actor] >= _am.
        // Choose _am in (0, preBalance] so the mutant will perform the subtraction and call.
        // If preBalance == 0, no admissible amount makes the mutant change balance; skip.
        vm.assume(preBalance > 0);
        uint256 am = bound(amount, 1, preBalance);

        uint256 balanceBefore = c.balances(actor);

        // Collect with the actor; the reference should do nothing (guard false), the mutant reduces balance.
        vm.prank(actor);
        try c.Collect(am) {
            // call may succeed
        } catch {}

        uint256 balanceAfter = c.balances(actor);

        // General rule: if the actor's pre-call balance was strictly below MinSum,
        // a call to Collect must never decrease it. Reference obeys; mutant breaks it for some inputs.
        assertTrue(balanceBefore < minSum ? balanceAfter >= balanceBefore : true);
    }
}
